package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	var cs [20][8][8]byte

	for i := 0; i < 8; i++ {
		if scanner.Scan() {
			line := scanner.Bytes()
			copy(cs[0][i][:], line)
		}
	}

	for i := 0; i < 19; i++ {
		for y := 0; y < 8; y++ {
			for x := 0; x < 8; x++ {
				if cs[i][y][x] == 'M' {
					for dy := -1; dy <= 1; dy++ {
						for dx := -1; dx <= 1; dx++ {
							xx := x + dx
							yy := y + dy
							if 0 <= xx && xx < 8 && 0 <= yy && yy < 8 && cs[i][yy][xx] != 'S' {
								cs[i+1][yy][xx] = 'M'
							}
						}
					}
				}
			}
		}

		for y := 6; y >= 0; y-- {
			for x := 0; x < 8; x++ {
				if cs[i][y][x] == 'S' {
					cs[i+1][y+1][x] = 'S'
				}
			}
		}
	}

	res := "LOSE"
	for y := 0; y < 8; y++ {
		for x := 0; x < 8; x++ {
			if cs[19][y][x] == 'M' {
				res = "WIN"
			}
		}
	}
	fmt.Println(res)
}

